scenarios.example_code:
import { declareEvent, spawnDispatchTasks } from '@projexlight/sdk-storm';
const e = await declareEvent({
  tenant_id, kind: 'hurricane', severity: 3,
  geo_extent: NHC_polygon, expected_closed_at: addDays(7),
});
await spawnDispatchTasks({ event_id: e.event_id, skill: 'storm-triage', priority: 'critical' });

// driven by the feed poller:
startFeedPoller({ tenant_id, feed: 'grid-outage-us-fl' });
// On crossing STORM_AUTO_DECLARE_THRESHOLD, the poller calls declareEvent + alerts oncall.

// poller calls into sdk-storm:
await ingestFeed({ tenant_id, feed: 'nhc-public-advisory', observation_time });
// per-cell update emits storm.intensity.updated.v1 to subscribers.

subscribeEvents('dispatch.task.completed.v1', async (e) => {
  recordCompletion(e); const ratio = spawnRate() / completionRate();
  if (ratio > 10) await throttleSpawn({ tenant_id, factor: 0.5 });
});
